method is_palindrome_recursive(s: string) returns (result: bool)
  requires pre(s)
  ensures spec(s, result)
  decreases |s|
{
  if py_len(s) <= 1 {
    return true;
  }
  if py_index(s, 0) != py_index(s, -1) {
    return false;
  }
  var pcc_t1 := is_palindrome_recursive(py_slice(s, 1, -1));
  return pcc_t1;
}
